// dedupe on import, so \"Time & Work\" cannot be created twice.\n  slug      String\n  category  TagCategory @default(TOPIC)\n  exam      Exam?\n  // Retired tags stop being offered on new questions but stay attached to the\n  // ones that already carry them, so historical filters keep working.\n  active    Boolean     @default(true)\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n\n  questions QuestionTag[]\n\n  @@unique([category, slug])\n  @@index([exam, category, active])\n  @@map(\"tags\")\n}\n\nmodel QuestionTag {\n  questionId String @map(\"question_id\")\n  tagId      String @map(\"tag_id\")\n\n  question Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  tag      Tag      @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([questionId, tagId])\n  @@index([tagId])\n  @@map(\"question_tags\")\n}\n\n// Sections, across every examination the platform supports. One enum rather\n// than one per exam: a question belongs to exactly one section, and keeping\n// them together means `sectionLimits`, subject filters and the per-subject\n// stats on a profile work for CAT without a parallel code path.\n//\n// Which members are legal is a function of the exam — see `examSections()` in\n// src/lib/exams.ts, which is what validation actually consults.\nenum Subject {\n  // SSC CGL\n  QUANT\n  REASONING\n  ENGLISH\n  GK\n  // CAT\n  VARC\n  DILR\n  QA\n}\n\nenum Difficulty {\n  EASY\n  MEDIUM\n  HARD\n}\n\n// How a question is answered, which decides how it is rendered and how it is\n// marked. STANDARD/SYLLOGISM/PASSAGE/TABLE are all single-choice and store\n// their key in `correctOption`; MSQ and TITA store theirs in `answerConfig`.\nenum QuestionType {\n  STANDARD\n  SYLLOGISM\n  PASSAGE\n  TABLE\n  // Multiple correct options. CAT marks these all-or-nothing by default.\n  MSQ\n  // Type In The Answer: no options at all, the candidate types a number or\n  // a word. CAT's non-MCQs carry no negative mark